// Store callback info for async processing
const crypto = require('crypto');
const input = $('Webhook').first().json;
const body = input.body || input;

// Generate or use provided job_id
const job_id = body.job_id || crypto.randomUUID();
const callback_url = body.callback_url;

return [{
  json: {
    ...input,
    _callback: {
      job_id,
      callback_url
    }
  }
}];

// Prepare data for Veo Video node (sync mode)
const input = $('Webhook').first().json;
const body = input.body || input;

// Get operation from request (default: generateFromText)
const operation = body.operation || 'generateFromText';

// Video parameters
const model = body.model || 'veo-3.1-generate-001';
const durationSeconds = body.durationSeconds || 6;
const aspectRatio = body.aspectRatio || '16:9';
const resolution = body.resolution || '1080p';
const generateAudio = body.generateAudio !== false;
const enhancePrompt = body.enhancePrompt !== false;
const personGeneration = body.personGeneration || 'allow_adult';
const preset = body.preset || 'none';

// Build result
const result = {
  operation,
  prompt: body.prompt || '',
  model,
  durationSeconds,
  aspectRatio,
  resolution,
  generateAudio,
  enhancePrompt,
  personGeneration,
  preset,
  originalRequest: { ...body }
};

// For generateFromImage
if (operation === 'generateFromImage') {
  result.sourceImage = body.sourceImage || '';
  result.sourceImageMimeType = body.sourceImageMimeType || 'image/png';
}

// For generateLongVideo
if (operation === 'generateLongVideo') {
  result.targetDuration = body.targetDuration || 30;
}

// For extendVideo
if (operation === 'extendVideo') {
  result.sourceVideo = body.sourceVideo || '';
  result.extensionPrompt = body.extensionPrompt || '';
}

return [{ json: result }];

