// Prepare callback payload for success
const input = $input.first().json;
const _callback = input._callback;

// Remove internal _callback from the payload
const { _callback: _, ...data } = input;

const body = {
  success: true,
  job_id: _callback.job_id,
  status: 'completed',
  data
};

return [{
  json: {
    body,
    callback_url: _callback.callback_url
  }
}];

// Compute HMAC signature (RFC-040 format)
const crypto = require('crypto');
const input = $input.first().json;

const secret = $env.N8N_WEBHOOK_SECRET || 'default-secret';
const payload = JSON.stringify(input.body);

// Sign body only, output hex WITHOUT prefix
const signature = crypto.createHmac('sha256', secret).update(payload).digest('hex');

return [{
  json: {
    ...input,
    signature
  }
}];

// Prepare error callback payload
const _callback = $('Prepare Config (Async)').first().json._callback;

// Get error information
let errorMessage = 'Unknown error occurred';
let errorDetails = {};

try {
  const input = $input.first().json;
  if (input.error) {
    errorMessage = input.error.message || input.error;
    errorDetails = input.error;
  } else if (input.message) {
    errorMessage = input.message;
  }
} catch (e) {
  errorMessage = 'Video generation failed';
}

const body = {
  success: false,
  job_id: _callback.job_id,
  status: 'failed',
  error: {
    message: errorMessage,
    details: errorDetails
  }
};

return [{
  json: {
    body,
    callback_url: _callback.callback_url
  }
}];

